-- Carga inicial de "Contactos externos": Academia Judicial, CBR y
-- Notarias, Cortes del pais, Receptores y Procuradores del Numero, y
-- Juzgados de Policia Local. Datos de solo consulta (no editables desde
-- la plataforma por ahora), cargados desde la planilla de referencia.

create table if not exists contactos_externos (
  id text primary key,
  categoria text not null,
  institucion text,
  nombre text,
  cargo text,
  comuna text,
  correos text[] not null default '{}',
  telefonos text[] not null default '{}',
  direccion text,
  calidad_juridica text,
  observaciones text,
  orden integer not null default 0,
  updated_at timestamptz not null default now()
);

alter table contactos_externos enable row level security;

drop policy if exists "lectura publica contactos_externos" on contactos_externos;
create policy "lectura publica contactos_externos" on contactos_externos for select using (true);

delete from contactos_externos;

